export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    // 本实例变量：保存监听器观察到的最新值
    let observed: number | null = null;

    // 注册 listener 监听 counter.value 事件
    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: { data?: unknown }) => {
        const data = event?.data as { value?: unknown } | undefined;
        if (data && typeof data.value === 'number') {
          observed = data.value;
        }
      },
    });

    // 注册 emit_value 工具：发射值并返回监听器观察到的值
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.0',
        description: 'Emit a value on the counter.value event and return the value observed by the listener.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            value: { type: 'number', description: 'Value to emit on counter.value. Defaults to 27.' },
          },
        },
        outputSchema: {
          type: 'object',
          properties: {
            emitted: { type: 'number' },
            observed: { type: 'number' },
          },
          required: ['emitted', 'observed'],
        },
        async handler(args: unknown) {
          const { value } = (args ?? {}) as { value?: number };
          const emitted = typeof value === 'number' ? value : 27;
          observed = null;
          await ctx.bus.emitAsync({ type: 'counter.value', ts: Date.now(), data: { value: emitted } });
          return { ok: true, data: { emitted, observed } };
        },
      },
    });
  },
};

export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.1',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    let observed: number | null = null;
    const log: unknown[] = [];

    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: unknown) => {
        log.push({ via: 'register', event });
        const data = (event as { data?: { value?: unknown } } | null)?.data;
        if (data && typeof data.value === 'number') observed = data.value;
      },
    });

    ctx.on('counter.value', (event: unknown) => {
      log.push({ via: 'on', event });
    });

    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.1',
        description: 'Diagnostic emit on counter.value.',
        permissions: [],
        sideEffect: 'none',
        parameters: { type: 'object', properties: { value: { type: 'number' } } },
        outputSchema: { type: 'object' },
        async handler(args: unknown) {
          const { value } = (args ?? {}) as { value?: number };
          const emitted = typeof value === 'number' ? value : 27;
          observed = null;
          log.length = 0;
          const busKeys = Object.keys(ctx.bus as object);
          let syncResult: unknown;
          let asyncResult: unknown;
          let syncError: string | null = null;
          let asyncError: string | null = null;
          try { syncResult = ctx.bus.emit({ type: 'counter.value', ts: Date.now(), data: { value: emitted } }); }
          catch (e) { syncError = String(e); }
          try { asyncResult = await ctx.bus.emitAsync({ type: 'counter.value', ts: Date.now(), data: { value: emitted } }); }
          catch (e) { asyncError = String(e); }
          return { ok: true, data: {
            emitted, observed, log, busKeys,
            syncResult: JSON.parse(JSON.stringify(syncResult ?? null)),
            asyncResult: JSON.parse(JSON.stringify(asyncResult ?? null)),
            syncError, asyncError,
          } };
        },
      },
    });
  },
};

